type QueryState = {
  hasTable: boolean;
  hasFields: boolean;
};

export class TypedQueryBuilder<TState extends QueryState = { hasTable: false; hasFields: false }> {
  private table = '';
  private fields: string[] = [];
  private conditions: string[] = [];

  from(table: string): TypedQueryBuilder<{ hasTable: true; hasFields: TState['hasFields'] }> {
    this.table = table;
    return this as any;
  }

  select(...fields: string[]): TypedQueryBuilder<{ hasTable: TState['hasTable']; hasFields: true }> {
    this.fields = fields;
    return this as any;
  }

  where(condition: string): this {
    this.conditions.push(condition);
    return this;
  }

  build(this: TypedQueryBuilder<{ hasTable: true; hasFields: true }>): string {
    const cols = this.fields.length > 0 ? this.fields.join(', ') : '*';
    let sql = `SELECT ${cols} FROM ${this.table}`;
    if (this.conditions.length > 0) {
      sql += ` WHERE ${this.conditions.join(' AND ')}`;
    }
    return sql;
  }
}
